// apü client runtime for Swift (Foundation only; Swift 6 language mode). Embedded into every file
// generated by `apue-types --lang swift`; the generated part below adds the API's types and a Client
// with one method per op. Transport: URLSession (HTTP/2 via ALPN where the server offers it).
// Covers: unary calls (GET ?i= with canonical JSON for cacheable reads when the URL fits 2048 chars,
// POST otherwise, Idempotency-Key for non-safe calls, retries for safe/keyed calls on connection loss
// and 429/503 honouring Retry-After, and on 409 retryable), server streams, client and bidi streams
// (request bodies streamed through a bound stream pair; full duplex over HTTP/2 on Apple platforms),
// RFC 9457 problems including END-frame errors, deadlines (apue-timeout) and Task cancellation,
// bytes in messages (BLOB frames, {"$blob": k} / {"$lit": …}), uploads for bytes/file inputs (one
// request each, deleted after the call), t.download() outputs (resumed with Range + If-Range,
// SHA-256 verified), certificate pinning (Apple platforms).
// Not covered: resuming broken streams (checkpoints are ignored), batches, QUERY (large reads are
// POSTed), field selection, client-side validation (the server validates), back-pressure on
// response bodies (URLSession delivers into memory as fast as the network allows).
// Linux: compiles against FoundationNetworking (no CryptoKit: a portable SHA-256; no pinning:
// install the CA in the system trust store) — not tested there.
import Foundation
#if canImport(FoundationNetworking)
import FoundationNetworking
#endif
#if canImport(CryptoKit)
import CryptoKit
#endif
#if canImport(Security)
import Security
#endif

// MARK: - Errors

/// An RFC 9457 problem: the call failed with `status` (HTTP semantics). `problem` is the raw object.
public struct ApueError: Error, Sendable, CustomStringConvertible, LocalizedError {
  public let status: Int
  public let type: String
  public let title: String
  public let detail: String?
  public let retryable: Bool
  public let problem: JSONValue

  public init(status: Int, problem: JSONValue) {
    self.status = status
    self.problem = problem
    if case .string(let type)? = problem["type"] { self.type = type } else { self.type = "about:blank" }
    if case .string(let title)? = problem["title"] { self.title = title } else { self.title = ApueError.phrase(status) }
    if case .string(let detail)? = problem["detail"] { self.detail = detail } else { self.detail = nil }
    self.retryable = problem["retryable"] == .bool(true)
  }

  init(_ status: Int, _ title: String, _ detail: String? = nil) {
    var object: [String: JSONValue] = ["title": .string(title), "status": .number(Double(status))]
    if let detail { object["detail"] = .string(detail) }
    self.init(status: status, problem: .object(object))
  }

  public var description: String { "\(status) \(title)" + (detail.map { ": \($0)" } ?? "") }
  public var errorDescription: String? { description }

  static func phrase(_ status: Int) -> String {
    let text = HTTPURLResponse.localizedString(forStatusCode: status)
    return text.prefix(1).uppercased() + text.dropFirst()
  }

  static func malformed(_ detail: String) -> ApueError { ApueError(502, "Malformed Stream", detail) }
  static func truncated(_ detail: String) -> ApueError { ApueError(502, "Truncated Stream", detail) }
}

/// The client was configured with something this platform can't do.
public struct ApueConfigurationError: Error, Sendable, CustomStringConvertible {
  public let description: String
}

// MARK: - JSON values

/// Any JSON value — the type of `t.unknown()` fields.
public enum JSONValue: Sendable, Hashable, Codable, ExpressibleByNilLiteral, ExpressibleByBooleanLiteral,
  ExpressibleByIntegerLiteral, ExpressibleByFloatLiteral, ExpressibleByStringLiteral, ExpressibleByArrayLiteral,
  ExpressibleByDictionaryLiteral
{
  case null
  case bool(Bool)
  case number(Double)
  case string(String)
  case array([JSONValue])
  case object([String: JSONValue])

  public init(nilLiteral: ()) { self = .null }
  public init(booleanLiteral value: Bool) { self = .bool(value) }
  public init(integerLiteral value: Int) { self = .number(Double(value)) }
  public init(floatLiteral value: Double) { self = .number(value) }
  public init(stringLiteral value: String) { self = .string(value) }
  public init(arrayLiteral elements: JSONValue...) { self = .array(elements) }
  public init(dictionaryLiteral elements: (String, JSONValue)...) {
    self = .object(Dictionary(elements, uniquingKeysWith: { _, last in last }))
  }

  /// The member `key` of an object (nil for other values or a missing member).
  public subscript(key: String) -> JSONValue? {
    if case .object(let object) = self { return object[key] }
    return nil
  }

  public init(from decoder: Decoder) throws {
    let container = try decoder.singleValueContainer()
    if container.decodeNil() {
      self = .null
    } else if let value = try? container.decode(Bool.self) {
      self = .bool(value)
    } else if let value = try? container.decode(Double.self) {
      self = .number(value)
    } else if let value = try? container.decode(String.self) {
      self = .string(value)
    } else if let value = try? container.decode([JSONValue].self) {
      self = .array(value)
    } else {
      self = .object(try container.decode([String: JSONValue].self))
    }
  }

  public func encode(to encoder: Encoder) throws {
    var container = encoder.singleValueContainer()
    switch self {
    case .null: try container.encodeNil()
    case .bool(let value): try container.encode(value)
    case .number(let value): try container.encode(value)
    case .string(let value): try container.encode(value)
    case .array(let value): try container.encode(value)
    case .object(let value): try container.encode(value)
    }
  }
}

/// A `t.file()` input: bytes in memory, a file on disk (streamed, never read into memory), or an
/// upload made earlier with `ApueClient.upload(_:)` (not deleted after the call).
public enum ApueFile: Sendable, Hashable, Codable {
  case data(Data)
  case file(URL)
  case upload(String)

  public init(from decoder: Decoder) throws {
    let container = try decoder.container(keyedBy: ApueKey.self)
    self = .upload(try container.decode(String.self, forKey: ApueKey("$upload")))
  }

  public func encode(to encoder: Encoder) throws {
    guard case .upload(let id) = self else {
      throw EncodingError.invalidValue(self, .init(codingPath: encoder.codingPath, debugDescription: "upload the file first (ApueClient.upload)"))
    }
    var container = encoder.container(keyedBy: ApueKey.self)
    try container.encode(id, forKey: ApueKey("$upload"))
  }
}

/// A coding key for any string (used by generated code for objects without fields).
public struct ApueKey: CodingKey, Sendable {
  public let stringValue: String
  public var intValue: Int? { Int(stringValue) }
  public init(_ string: String) { stringValue = string }
  public init?(stringValue: String) { self.stringValue = stringValue }
  public init?(intValue: Int) { stringValue = String(intValue) }
}

/// The wire tree: JSON plus binary values (sent as BLOB frames or uploads, never as base64).
enum Node: Sendable, Equatable {
  case null
  case bool(Bool)
  case number(Double)
  case string(String)
  case array([Node])
  case object([String: Node])
  case bytes(Data)
  case file(ApueFile)

  init(_ value: JSONValue) {
    switch value {
    case .null: self = .null
    case .bool(let v): self = .bool(v)
    case .number(let v): self = .number(v)
    case .string(let v): self = .string(v)
    case .array(let v): self = .array(v.map(Node.init))
    case .object(let v): self = .object(v.mapValues(Node.init))
    }
  }

  func json(_ path: [CodingKey] = []) throws -> JSONValue {
    switch self {
    case .null: return .null
    case .bool(let v): return .bool(v)
    case .number(let v): return .number(v)
    case .string(let v): return .string(v)
    case .array(let v): return .array(try v.map { try $0.json(path) })
    case .object(let v): return .object(try v.mapValues { try $0.json(path) })
    case .bytes, .file:
      throw DecodingError.typeMismatch(JSONValue.self, .init(codingPath: path, debugDescription: "binary value where JSON was expected"))
    }
  }

  subscript(key: String) -> Node? {
    if case .object(let object) = self { return object[key] }
    return nil
  }
}

// MARK: - JSON text (RFC 8259; canonical form after RFC 8785: sorted keys, ES number formatting)

enum JSONText {
  static func parse(_ data: Data) throws -> Node {
    var parser = Parser(bytes: [UInt8](data))
    parser.skipSpace()
    let value = try parser.value(depth: 0)
    parser.skipSpace()
    guard parser.index == parser.bytes.count else { throw parser.error("trailing data") }
    return value
  }

  static func serialize(_ node: Node, canonical: Bool = false) throws -> Data {
    var out = ""
    try write(node, canonical: canonical, into: &out)
    return Data(out.utf8)
  }

  static func string(_ node: Node, canonical: Bool = false) throws -> String {
    var out = ""
    try write(node, canonical: canonical, into: &out)
    return out
  }

  private static func write(_ node: Node, canonical: Bool, into out: inout String) throws {
    switch node {
    case .null: out += "null"
    case .bool(let v): out += v ? "true" : "false"
    case .number(let v): out += try number(v)
    case .string(let v): quote(v, into: &out)
    case .array(let items):
      out += "["
      for (i, item) in items.enumerated() {
        if i > 0 { out += "," }
        try write(item, canonical: canonical, into: &out)
      }
      out += "]"
    case .object(let members):
      out += "{"
      // RFC 8785 §3.2.3: keys sorted by their UTF-16 code units.
      let keys = canonical ? members.keys.sorted { $0.utf16.lexicographicallyPrecedes($1.utf16) } : Array(members.keys)
      for (i, key) in keys.enumerated() {
        if i > 0 { out += "," }
        quote(key, into: &out)
        out += ":"
        try write(members[key]!, canonical: canonical, into: &out)
      }
      out += "}"
    case .bytes, .file:
      throw EncodingError.invalidValue(node, .init(codingPath: [], debugDescription: "binary value outside a bytes position"))
    }
  }

  /// JSON.stringify's string escaping (= RFC 8785 §3.2.2.2).
  static func quote(_ text: String, into out: inout String) {
    out += "\""
    for scalar in text.unicodeScalars {
      switch scalar {
      case "\"": out += "\\\""
      case "\\": out += "\\\\"
      case "\u{08}": out += "\\b"
      case "\u{0C}": out += "\\f"
      case "\n": out += "\\n"
      case "\r": out += "\\r"
      case "\t": out += "\\t"
      default:
        if scalar.value < 0x20 {
          let hex = String(scalar.value, radix: 16)
          out += "\\u" + String(repeating: "0", count: 4 - hex.count) + hex
        } else {
          out.unicodeScalars.append(scalar)
        }
      }
    }
    out += "\""
  }

  /// ECMAScript Number::toString (RFC 8785 §3.2.2.3), from Swift's shortest round-trip digits.
  static func number(_ value: Double) throws -> String {
    guard value.isFinite else {
      throw EncodingError.invalidValue(value, .init(codingPath: [], debugDescription: "NaN and infinities are not JSON"))
    }
    if value == 0 { return "0" }
    let negative = value < 0
    let text = (negative ? -value : value).description  // e.g. "123.0", "1e-07", "1.5e+300"
    let parts = text.split(separator: "e", maxSplits: 1)
    let exponent = parts.count == 2 ? Int(parts[1])! : 0
    let mantissa = parts[0].split(separator: ".", omittingEmptySubsequences: false)
    var digits = Array(mantissa[0] + (mantissa.count > 1 ? mantissa[1] : ""))
    var n = mantissa[0].count + exponent  // value = 0.digits × 10^n
    while digits.first == "0" { digits.removeFirst(); n -= 1 }
    while digits.last == "0" { digits.removeLast() }
    let k = digits.count
    let s = String(digits)
    var result: String
    if k <= n && n <= 21 {
      result = s + String(repeating: "0", count: n - k)
    } else if 0 < n && n <= 21 {
      result = String(digits[..<n]) + "." + String(digits[n...])
    } else if -6 < n && n <= 0 {
      result = "0." + String(repeating: "0", count: -n) + s
    } else {
      let e = n - 1
      let sign = e < 0 ? "-" : "+"
      result = (k == 1 ? s : String(digits[0]) + "." + String(digits[1...])) + "e" + sign + String(abs(e))
    }
    return negative ? "-" + result : result
  }

  struct Parser {
    let bytes: [UInt8]
    var index = 0

    func error(_ message: String) -> ApueError { .malformed("invalid JSON at byte \(index): \(message)") }

    mutating func skipSpace() {
      while index < bytes.count, [0x20, 0x09, 0x0A, 0x0D].contains(bytes[index]) { index += 1 }
    }

    mutating func value(depth: Int) throws -> Node {
      guard depth < 512 else { throw error("nested too deeply") }
      guard index < bytes.count else { throw error("unexpected end") }
      switch bytes[index] {
      case UInt8(ascii: "{"):
        index += 1
        var members: [String: Node] = [:]
        skipSpace()
        if index < bytes.count, bytes[index] == UInt8(ascii: "}") { index += 1; return .object(members) }
        while true {
          skipSpace()
          guard index < bytes.count, bytes[index] == UInt8(ascii: "\"") else { throw error("expected a member name") }
          let key = try string()
          skipSpace()
          guard index < bytes.count, bytes[index] == UInt8(ascii: ":") else { throw error("expected ':'") }
          index += 1
          skipSpace()
          members[key] = try value(depth: depth + 1)
          skipSpace()
          guard index < bytes.count else { throw error("unexpected end") }
          if bytes[index] == UInt8(ascii: ",") { index += 1; continue }
          guard bytes[index] == UInt8(ascii: "}") else { throw error("expected ',' or '}'") }
          index += 1
          return .object(members)
        }
      case UInt8(ascii: "["):
        index += 1
        var items: [Node] = []
        skipSpace()
        if index < bytes.count, bytes[index] == UInt8(ascii: "]") { index += 1; return .array(items) }
        while true {
          skipSpace()
          items.append(try value(depth: depth + 1))
          skipSpace()
          guard index < bytes.count else { throw error("unexpected end") }
          if bytes[index] == UInt8(ascii: ",") { index += 1; continue }
          guard bytes[index] == UInt8(ascii: "]") else { throw error("expected ',' or ']'") }
          index += 1
          return .array(items)
        }
      case UInt8(ascii: "\""):
        return .string(try string())
      case UInt8(ascii: "t"): try literal("true"); return .bool(true)
      case UInt8(ascii: "f"): try literal("false"); return .bool(false)
      case UInt8(ascii: "n"): try literal("null"); return .null
      default:
        let start = index
        while index < bytes.count, "+-0123456789.eE".utf8.contains(bytes[index]) { index += 1 }
        guard index > start, let number = Double(String(decoding: bytes[start..<index], as: UTF8.self)), number.isFinite else {
          throw error("invalid number")
        }
        return .number(number)
      }
    }

    mutating func literal(_ word: String) throws {
      let utf8 = Array(word.utf8)
      guard index + utf8.count <= bytes.count, Array(bytes[index..<index + utf8.count]) == utf8 else { throw error("invalid literal") }
      index += utf8.count
    }

    mutating func hex4() throws -> UInt32 {
      guard index + 4 <= bytes.count, let value = UInt32(String(decoding: bytes[index..<index + 4], as: UTF8.self), radix: 16) else {
        throw error("invalid \\u escape")
      }
      index += 4
      return value
    }

    mutating func string() throws -> String {
      index += 1  // opening quote
      var out: [UInt8] = []
      while index < bytes.count {
        let byte = bytes[index]
        if byte == UInt8(ascii: "\"") {
          index += 1
          return String(decoding: out, as: UTF8.self)
        }
        guard byte == UInt8(ascii: "\\") else {
          guard byte >= 0x20 else { throw error("control character in string") }
          out.append(byte)
          index += 1
          continue
        }
        guard index + 1 < bytes.count else { break }
        let escape = bytes[index + 1]
        index += 2
        switch escape {
        case UInt8(ascii: "\""), UInt8(ascii: "\\"), UInt8(ascii: "/"): out.append(escape)
        case UInt8(ascii: "b"): out.append(0x08)
        case UInt8(ascii: "f"): out.append(0x0C)
        case UInt8(ascii: "n"): out.append(0x0A)
        case UInt8(ascii: "r"): out.append(0x0D)
        case UInt8(ascii: "t"): out.append(0x09)
        case UInt8(ascii: "u"):
          var code = try hex4()
          if (0xD800..<0xDC00).contains(code), index + 6 <= bytes.count, bytes[index] == UInt8(ascii: "\\"), bytes[index + 1] == UInt8(ascii: "u") {
            let save = index
            index += 2
            let low = try hex4()
            if (0xDC00..<0xE000).contains(low) {
              code = 0x10000 + ((code - 0xD800) << 10) + (low - 0xDC00)
            } else {
              index = save
            }
          }
          out.append(contentsOf: Array(String(Character(Unicode.Scalar(code) ?? "\u{FFFD}")).utf8))
        default: throw error("invalid escape")
        }
      }
      throw error("unterminated string")
    }
  }
}

// MARK: - Codable ↔ Node (Data stays binary, JSONValue and ApueFile pass through)

final class EncodingBox {
  var value: Node?
  var object: [String: EncodingBox]?
  var array: [EncodingBox]?

  var node: Node {
    if let object { return .object(object.mapValues(\.node)) }
    if let array { return .array(array.map(\.node)) }
    return value ?? .object([:])
  }

  static func box<T: Encodable>(_ value: T, _ path: [CodingKey]) throws -> EncodingBox {
    let box = EncodingBox()
    if let data = value as? Data {
      box.value = .bytes(data)
    } else if let file = value as? ApueFile {
      box.value = .file(file)
    } else if let json = value as? JSONValue {
      box.value = Node(json)
    } else {
      try value.encode(to: NodeEncoder(box: box, codingPath: path))
    }
    return box
  }
}

struct NodeEncoder: Encoder {
  let box: EncodingBox
  let codingPath: [CodingKey]
  var userInfo: [CodingUserInfoKey: Any] { [:] }

  static func encode<T: Encodable>(_ value: T) throws -> Node { try EncodingBox.box(value, []).node }

  func container<Key: CodingKey>(keyedBy type: Key.Type) -> KeyedEncodingContainer<Key> {
    if box.object == nil { box.object = [:] }
    return KeyedEncodingContainer(KeyedNodeEncoder<Key>(box: box, codingPath: codingPath))
  }

  func unkeyedContainer() -> UnkeyedEncodingContainer {
    if box.array == nil { box.array = [] }
    return UnkeyedNodeEncoder(box: box, codingPath: codingPath)
  }

  func singleValueContainer() -> SingleValueEncodingContainer { SingleNodeEncoder(box: box, codingPath: codingPath) }
}

private func finite(_ value: Double, _ path: [CodingKey]) throws -> Node {
  guard value.isFinite else { throw EncodingError.invalidValue(value, .init(codingPath: path, debugDescription: "NaN and infinities are not JSON")) }
  return .number(value)
}

struct KeyedNodeEncoder<Key: CodingKey>: KeyedEncodingContainerProtocol {
  let box: EncodingBox
  let codingPath: [CodingKey]

  private func set(_ node: Node, _ key: Key) {
    let child = EncodingBox()
    child.value = node
    box.object![key.stringValue] = child
  }

  mutating func encodeNil(forKey key: Key) throws { set(.null, key) }
  mutating func encode(_ value: Bool, forKey key: Key) throws { set(.bool(value), key) }
  mutating func encode(_ value: String, forKey key: Key) throws { set(.string(value), key) }
  mutating func encode(_ value: Double, forKey key: Key) throws { set(try finite(value, codingPath + [key]), key) }
  mutating func encode(_ value: Float, forKey key: Key) throws { set(try finite(Double(value), codingPath + [key]), key) }
  mutating func encode(_ value: Int, forKey key: Key) throws { set(.number(Double(value)), key) }
  mutating func encode(_ value: Int8, forKey key: Key) throws { set(.number(Double(value)), key) }
  mutating func encode(_ value: Int16, forKey key: Key) throws { set(.number(Double(value)), key) }
  mutating func encode(_ value: Int32, forKey key: Key) throws { set(.number(Double(value)), key) }
  mutating func encode(_ value: Int64, forKey key: Key) throws { set(.number(Double(value)), key) }
  mutating func encode(_ value: UInt, forKey key: Key) throws { set(.number(Double(value)), key) }
  mutating func encode(_ value: UInt8, forKey key: Key) throws { set(.number(Double(value)), key) }
  mutating func encode(_ value: UInt16, forKey key: Key) throws { set(.number(Double(value)), key) }
  mutating func encode(_ value: UInt32, forKey key: Key) throws { set(.number(Double(value)), key) }
  mutating func encode(_ value: UInt64, forKey key: Key) throws { set(.number(Double(value)), key) }
  mutating func encode<T: Encodable>(_ value: T, forKey key: Key) throws {
    box.object![key.stringValue] = try EncodingBox.box(value, codingPath + [key])
  }

  mutating func nestedContainer<NestedKey: CodingKey>(keyedBy keyType: NestedKey.Type, forKey key: Key) -> KeyedEncodingContainer<NestedKey> {
    let child = EncodingBox()
    box.object![key.stringValue] = child
    return NodeEncoder(box: child, codingPath: codingPath + [key]).container(keyedBy: keyType)
  }

  mutating func nestedUnkeyedContainer(forKey key: Key) -> UnkeyedEncodingContainer {
    let child = EncodingBox()
    box.object![key.stringValue] = child
    return NodeEncoder(box: child, codingPath: codingPath + [key]).unkeyedContainer()
  }

  mutating func superEncoder() -> Encoder { superEncoder(forKey: Key(stringValue: "super")!) }

  mutating func superEncoder(forKey key: Key) -> Encoder {
    let child = EncodingBox()
    box.object![key.stringValue] = child
    return NodeEncoder(box: child, codingPath: codingPath + [key])
  }
}

struct UnkeyedNodeEncoder: UnkeyedEncodingContainer {
  let box: EncodingBox
  let codingPath: [CodingKey]
  var count: Int { box.array!.count }

  private func append(_ node: Node) {
    let child = EncodingBox()
    child.value = node
    box.array!.append(child)
  }

  private var key: CodingKey { ApueKey(String(count)) }

  mutating func encodeNil() throws { append(.null) }
  mutating func encode(_ value: Bool) throws { append(.bool(value)) }
  mutating func encode(_ value: String) throws { append(.string(value)) }
  mutating func encode(_ value: Double) throws { append(try finite(value, codingPath + [key])) }
  mutating func encode(_ value: Float) throws { append(try finite(Double(value), codingPath + [key])) }
  mutating func encode(_ value: Int) throws { append(.number(Double(value))) }
  mutating func encode(_ value: Int8) throws { append(.number(Double(value))) }
  mutating func encode(_ value: Int16) throws { append(.number(Double(value))) }
  mutating func encode(_ value: Int32) throws { append(.number(Double(value))) }
  mutating func encode(_ value: Int64) throws { append(.number(Double(value))) }
  mutating func encode(_ value: UInt) throws { append(.number(Double(value))) }
  mutating func encode(_ value: UInt8) throws { append(.number(Double(value))) }
  mutating func encode(_ value: UInt16) throws { append(.number(Double(value))) }
  mutating func encode(_ value: UInt32) throws { append(.number(Double(value))) }
  mutating func encode(_ value: UInt64) throws { append(.number(Double(value))) }
  mutating func encode<T: Encodable>(_ value: T) throws { box.array!.append(try EncodingBox.box(value, codingPath + [key])) }

  mutating func nestedContainer<NestedKey: CodingKey>(keyedBy keyType: NestedKey.Type) -> KeyedEncodingContainer<NestedKey> {
    let child = EncodingBox()
    let path = codingPath + [key]
    box.array!.append(child)
    return NodeEncoder(box: child, codingPath: path).container(keyedBy: keyType)
  }

  mutating func nestedUnkeyedContainer() -> UnkeyedEncodingContainer {
    let child = EncodingBox()
    let path = codingPath + [key]
    box.array!.append(child)
    return NodeEncoder(box: child, codingPath: path).unkeyedContainer()
  }

  mutating func superEncoder() -> Encoder {
    let child = EncodingBox()
    let path = codingPath + [key]
    box.array!.append(child)
    return NodeEncoder(box: child, codingPath: path)
  }
}

struct SingleNodeEncoder: SingleValueEncodingContainer {
  let box: EncodingBox
  let codingPath: [CodingKey]

  mutating func encodeNil() throws { box.value = .null }
  mutating func encode(_ value: Bool) throws { box.value = .bool(value) }
  mutating func encode(_ value: String) throws { box.value = .string(value) }
  mutating func encode(_ value: Double) throws { box.value = try finite(value, codingPath) }
  mutating func encode(_ value: Float) throws { box.value = try finite(Double(value), codingPath) }
  mutating func encode(_ value: Int) throws { box.value = .number(Double(value)) }
  mutating func encode(_ value: Int8) throws { box.value = .number(Double(value)) }
  mutating func encode(_ value: Int16) throws { box.value = .number(Double(value)) }
  mutating func encode(_ value: Int32) throws { box.value = .number(Double(value)) }
  mutating func encode(_ value: Int64) throws { box.value = .number(Double(value)) }
  mutating func encode(_ value: UInt) throws { box.value = .number(Double(value)) }
  mutating func encode(_ value: UInt8) throws { box.value = .number(Double(value)) }
  mutating func encode(_ value: UInt16) throws { box.value = .number(Double(value)) }
  mutating func encode(_ value: UInt32) throws { box.value = .number(Double(value)) }
  mutating func encode(_ value: UInt64) throws { box.value = .number(Double(value)) }
  mutating func encode<T: Encodable>(_ value: T) throws {
    let inner = try EncodingBox.box(value, codingPath)
    box.value = inner.value
    box.object = inner.object
    box.array = inner.array
  }
}

struct NodeDecoder: Decoder {
  let node: Node
  let codingPath: [CodingKey]
  let userInfo: [CodingUserInfoKey: Any]

  static func decode<T: Decodable>(_ type: T.Type, from node: Node, userInfo: [CodingUserInfoKey: Any]) throws -> T {
    try unbox(type, node, [], userInfo)
  }

  static func unbox<T: Decodable>(_ type: T.Type, _ node: Node, _ path: [CodingKey], _ userInfo: [CodingUserInfoKey: Any]) throws -> T {
    if T.self == Data.self {
      guard case .bytes(let data) = node else { throw mismatch(Data.self, node, path) }
      return data as! T
    }
    if T.self == JSONValue.self { return try node.json(path) as! T }
    return try T(from: NodeDecoder(node: node, codingPath: path, userInfo: userInfo))
  }

  static func mismatch(_ type: Any.Type, _ node: Node, _ path: [CodingKey]) -> DecodingError {
    .typeMismatch(type, .init(codingPath: path, debugDescription: "expected \(type), found \(node)"))
  }

  func container<Key: CodingKey>(keyedBy type: Key.Type) throws -> KeyedDecodingContainer<Key> {
    guard case .object(let object) = node else { throw NodeDecoder.mismatch([String: Any].self, node, codingPath) }
    return KeyedDecodingContainer(KeyedNodeDecoder<Key>(object: object, codingPath: codingPath, userInfo: userInfo))
  }

  func unkeyedContainer() throws -> UnkeyedDecodingContainer {
    guard case .array(let array) = node else { throw NodeDecoder.mismatch([Any].self, node, codingPath) }
    return UnkeyedNodeDecoder(array: array, codingPath: codingPath, userInfo: userInfo)
  }

  func singleValueContainer() throws -> SingleValueDecodingContainer { SingleNodeDecoder(node: node, codingPath: codingPath, userInfo: userInfo) }
}

/// Scalars out of a node, with the checks JSONDecoder makes (no coercion, integers must be exact).
enum Scalar {
  static func bool(_ node: Node, _ path: [CodingKey]) throws -> Bool {
    guard case .bool(let value) = node else { throw NodeDecoder.mismatch(Bool.self, node, path) }
    return value
  }

  static func string(_ node: Node, _ path: [CodingKey]) throws -> String {
    guard case .string(let value) = node else { throw NodeDecoder.mismatch(String.self, node, path) }
    return value
  }

  static func double(_ node: Node, _ path: [CodingKey]) throws -> Double {
    guard case .number(let value) = node else { throw NodeDecoder.mismatch(Double.self, node, path) }
    return value
  }

  static func integer<I: FixedWidthInteger>(_ node: Node, _ path: [CodingKey]) throws -> I {
    guard case .number(let value) = node, let integer = I(exactly: value) else { throw NodeDecoder.mismatch(I.self, node, path) }
    return integer
  }
}

struct KeyedNodeDecoder<Key: CodingKey>: KeyedDecodingContainerProtocol {
  let object: [String: Node]
  let codingPath: [CodingKey]
  let userInfo: [CodingUserInfoKey: Any]

  var allKeys: [Key] { object.keys.compactMap { Key(stringValue: $0) } }
  func contains(_ key: Key) -> Bool { object[key.stringValue] != nil }

  private func node(_ key: Key) throws -> Node {
    guard let node = object[key.stringValue] else {
      throw DecodingError.keyNotFound(key, .init(codingPath: codingPath, debugDescription: "no member \"\(key.stringValue)\""))
    }
    return node
  }

  func decodeNil(forKey key: Key) throws -> Bool { try node(key) == .null }
  func decode(_ type: Bool.Type, forKey key: Key) throws -> Bool { try Scalar.bool(node(key), codingPath + [key]) }
  func decode(_ type: String.Type, forKey key: Key) throws -> String { try Scalar.string(node(key), codingPath + [key]) }
  func decode(_ type: Double.Type, forKey key: Key) throws -> Double { try Scalar.double(node(key), codingPath + [key]) }
  func decode(_ type: Float.Type, forKey key: Key) throws -> Float { Float(try Scalar.double(node(key), codingPath + [key])) }
  func decode(_ type: Int.Type, forKey key: Key) throws -> Int { try Scalar.integer(node(key), codingPath + [key]) }
  func decode(_ type: Int8.Type, forKey key: Key) throws -> Int8 { try Scalar.integer(node(key), codingPath + [key]) }
  func decode(_ type: Int16.Type, forKey key: Key) throws -> Int16 { try Scalar.integer(node(key), codingPath + [key]) }
  func decode(_ type: Int32.Type, forKey key: Key) throws -> Int32 { try Scalar.integer(node(key), codingPath + [key]) }
  func decode(_ type: Int64.Type, forKey key: Key) throws -> Int64 { try Scalar.integer(node(key), codingPath + [key]) }
  func decode(_ type: UInt.Type, forKey key: Key) throws -> UInt { try Scalar.integer(node(key), codingPath + [key]) }
  func decode(_ type: UInt8.Type, forKey key: Key) throws -> UInt8 { try Scalar.integer(node(key), codingPath + [key]) }
  func decode(_ type: UInt16.Type, forKey key: Key) throws -> UInt16 { try Scalar.integer(node(key), codingPath + [key]) }
  func decode(_ type: UInt32.Type, forKey key: Key) throws -> UInt32 { try Scalar.integer(node(key), codingPath + [key]) }
  func decode(_ type: UInt64.Type, forKey key: Key) throws -> UInt64 { try Scalar.integer(node(key), codingPath + [key]) }
  func decode<T: Decodable>(_ type: T.Type, forKey key: Key) throws -> T {
    try NodeDecoder.unbox(type, node(key), codingPath + [key], userInfo)
  }

  func nestedContainer<NestedKey: CodingKey>(keyedBy type: NestedKey.Type, forKey key: Key) throws -> KeyedDecodingContainer<NestedKey> {
    try NodeDecoder(node: node(key), codingPath: codingPath + [key], userInfo: userInfo).container(keyedBy: type)
  }

  func nestedUnkeyedContainer(forKey key: Key) throws -> UnkeyedDecodingContainer {
    try NodeDecoder(node: node(key), codingPath: codingPath + [key], userInfo: userInfo).unkeyedContainer()
  }

  func superDecoder() throws -> Decoder { try superDecoder(forKey: Key(stringValue: "super")!) }

  func superDecoder(forKey key: Key) throws -> Decoder {
    NodeDecoder(node: object[key.stringValue] ?? .null, codingPath: codingPath + [key], userInfo: userInfo)
  }
}

struct UnkeyedNodeDecoder: UnkeyedDecodingContainer {
  let array: [Node]
  let codingPath: [CodingKey]
  let userInfo: [CodingUserInfoKey: Any]
  var currentIndex = 0

  init(array: [Node], codingPath: [CodingKey], userInfo: [CodingUserInfoKey: Any]) {
    self.array = array
    self.codingPath = codingPath
    self.userInfo = userInfo
  }

  var count: Int? { array.count }
  var isAtEnd: Bool { currentIndex >= array.count }
  private var path: [CodingKey] { codingPath + [ApueKey(String(currentIndex))] }

  private mutating func next() throws -> Node {
    guard !isAtEnd else { throw DecodingError.valueNotFound(Any.self, .init(codingPath: path, debugDescription: "array exhausted")) }
    defer { currentIndex += 1 }
    return array[currentIndex]
  }

  mutating func decodeNil() throws -> Bool {
    guard !isAtEnd, array[currentIndex] == .null else { return false }
    currentIndex += 1
    return true
  }

  mutating func decode(_ type: Bool.Type) throws -> Bool { let p = path; return try Scalar.bool(next(), p) }
  mutating func decode(_ type: String.Type) throws -> String { let p = path; return try Scalar.string(next(), p) }
  mutating func decode(_ type: Double.Type) throws -> Double { let p = path; return try Scalar.double(next(), p) }
  mutating func decode(_ type: Float.Type) throws -> Float { let p = path; return Float(try Scalar.double(next(), p)) }
  mutating func decode(_ type: Int.Type) throws -> Int { let p = path; return try Scalar.integer(next(), p) }
  mutating func decode(_ type: Int8.Type) throws -> Int8 { let p = path; return try Scalar.integer(next(), p) }
  mutating func decode(_ type: Int16.Type) throws -> Int16 { let p = path; return try Scalar.integer(next(), p) }
  mutating func decode(_ type: Int32.Type) throws -> Int32 { let p = path; return try Scalar.integer(next(), p) }
  mutating func decode(_ type: Int64.Type) throws -> Int64 { let p = path; return try Scalar.integer(next(), p) }
  mutating func decode(_ type: UInt.Type) throws -> UInt { let p = path; return try Scalar.integer(next(), p) }
  mutating func decode(_ type: UInt8.Type) throws -> UInt8 { let p = path; return try Scalar.integer(next(), p) }
  mutating func decode(_ type: UInt16.Type) throws -> UInt16 { let p = path; return try Scalar.integer(next(), p) }
  mutating func decode(_ type: UInt32.Type) throws -> UInt32 { let p = path; return try Scalar.integer(next(), p) }
  mutating func decode(_ type: UInt64.Type) throws -> UInt64 { let p = path; return try Scalar.integer(next(), p) }
  mutating func decode<T: Decodable>(_ type: T.Type) throws -> T {
    let p = path
    return try NodeDecoder.unbox(type, next(), p, userInfo)
  }

  mutating func nestedContainer<NestedKey: CodingKey>(keyedBy type: NestedKey.Type) throws -> KeyedDecodingContainer<NestedKey> {
    let p = path
    return try NodeDecoder(node: next(), codingPath: p, userInfo: userInfo).container(keyedBy: type)
  }

  mutating func nestedUnkeyedContainer() throws -> UnkeyedDecodingContainer {
    let p = path
    return try NodeDecoder(node: next(), codingPath: p, userInfo: userInfo).unkeyedContainer()
  }

  mutating func superDecoder() throws -> Decoder {
    let p = path
    return NodeDecoder(node: try next(), codingPath: p, userInfo: userInfo)
  }
}

struct SingleNodeDecoder: SingleValueDecodingContainer {
  let node: Node
  let codingPath: [CodingKey]
  let userInfo: [CodingUserInfoKey: Any]

  func decodeNil() -> Bool { node == .null }
  func decode(_ type: Bool.Type) throws -> Bool { try Scalar.bool(node, codingPath) }
  func decode(_ type: String.Type) throws -> String { try Scalar.string(node, codingPath) }
  func decode(_ type: Double.Type) throws -> Double { try Scalar.double(node, codingPath) }
  func decode(_ type: Float.Type) throws -> Float { Float(try Scalar.double(node, codingPath)) }
  func decode(_ type: Int.Type) throws -> Int { try Scalar.integer(node, codingPath) }
  func decode(_ type: Int8.Type) throws -> Int8 { try Scalar.integer(node, codingPath) }
  func decode(_ type: Int16.Type) throws -> Int16 { try Scalar.integer(node, codingPath) }
  func decode(_ type: Int32.Type) throws -> Int32 { try Scalar.integer(node, codingPath) }
  func decode(_ type: Int64.Type) throws -> Int64 { try Scalar.integer(node, codingPath) }
  func decode(_ type: UInt.Type) throws -> UInt { try Scalar.integer(node, codingPath) }
  func decode(_ type: UInt8.Type) throws -> UInt8 { try Scalar.integer(node, codingPath) }
  func decode(_ type: UInt16.Type) throws -> UInt16 { try Scalar.integer(node, codingPath) }
  func decode(_ type: UInt32.Type) throws -> UInt32 { try Scalar.integer(node, codingPath) }
  func decode(_ type: UInt64.Type) throws -> UInt64 { try Scalar.integer(node, codingPath) }
  func decode<T: Decodable>(_ type: T.Type) throws -> T { try NodeDecoder.unbox(type, node, codingPath, userInfo) }
}

// MARK: - Frames and binary values (SPEC §6)

enum Frame {
  static let msg: UInt8 = 0x00, end: UInt8 = 0x01, blob: UInt8 = 0x02
  static let last: UInt8 = 0x02
  static let blobChunk = 64 * 1024
  /// Clients accept up to 64 MiB per message (frames and the blobs of one message).
  static let maxMessage = 64 * 1024 * 1024

  static func encode(_ type: UInt8, _ payload: Data, flags: UInt8 = 0) -> Data {
    var out = Data(capacity: 8 + payload.count)
    let length = UInt32(payload.count)
    out.append(contentsOf: [type, flags, 0, 0, UInt8(length >> 24), UInt8(length >> 16 & 0xFF), UInt8(length >> 8 & 0xFF), UInt8(length & 0xFF)])
    out.append(payload)
    return out
  }

  /// Frames for one message: BLOB chunks for every binary value, then the MSG frame. Without
  /// binary values in the schema (`bytes` false) the message is plain JSON, nothing escaped.
  static func message(_ value: Node, bytes: Bool) throws -> Data {
    guard bytes else { return encode(msg, try JSONText.serialize(value)) }
    var blobs: [Data] = []
    let json = split(value, &blobs)
    var out = Data()
    for blob in blobs {
      if blob.isEmpty { out.append(encode(Frame.blob, Data(), flags: last)) }
      var offset = blob.startIndex
      while offset < blob.endIndex {
        let end = min(offset + blobChunk, blob.endIndex)
        out.append(encode(Frame.blob, blob[offset..<end], flags: end == blob.endIndex ? last : 0))
        offset = end
      }
    }
    out.append(encode(msg, try JSONText.serialize(json)))
    return out
  }

  /// bytes → {"$blob": k}; look-alikes ({"$blob"} or {"$lit"} as the only member) → {"$lit": value}.
  static func split(_ value: Node, _ blobs: inout [Data]) -> Node {
    switch value {
    case .bytes(let data):
      blobs.append(data)
      return .object(["$blob": .number(Double(blobs.count - 1))])
    case .array(let items):
      return .array(items.map { split($0, &blobs) })
    case .object(let members):
      if members.count == 1, let key = members.keys.first, key == "$blob" || key == "$lit" { return .object(["$lit": value]) }
      return .object(members.mapValues { split($0, &blobs) })
    default:
      return value
    }
  }

  /// {"$blob": k} → the k-th blob (each exactly once); {"$lit": v} → v verbatim.
  static func restore(_ value: Node, _ blobs: [Data], _ used: inout Set<Int>) throws -> Node {
    switch value {
    case .array(let items):
      return .array(try items.map { try restore($0, blobs, &used) })
    case .object(let members):
      if members.count == 1, let literal = members["$lit"] { return literal }
      if members.count == 1, let reference = members["$blob"] {
        guard case .number(let k) = reference, let index = Int(exactly: k), blobs.indices.contains(index), !used.contains(index) else {
          throw ApueError.malformed("invalid blob reference \(reference)")
        }
        used.insert(index)
        return .bytes(blobs[index])
      }
      var out: [String: Node] = [:]
      for (key, member) in members { out[key] = try restore(member, blobs, &used) }
      return .object(out)
    default:
      return value
    }
  }
}

// MARK: - SHA-256 (CryptoKit where available, else portable)

struct SHA256Hasher {
  #if canImport(CryptoKit)
  private var hasher = CryptoKit.SHA256()
  mutating func update(_ data: Data) { hasher.update(data: data) }
  func hex() -> String { hasher.finalize().map { String(format: "%02x", $0) }.joined() }
  #else
  private var hasher = PortableSHA256()
  mutating func update(_ data: Data) { hasher.update(data) }
  func hex() -> String { hasher.hex() }
  #endif
}

/// FIPS 180-4 SHA-256 for platforms without CryptoKit (Linux). Always compiled, so it can be tested.
struct PortableSHA256 {
  private static let k: [UInt32] = [
    0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5, 0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3,
    0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174, 0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
    0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967, 0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13,
    0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85, 0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
    0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3, 0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208,
    0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
  ]
  private var state: [UInt32] = [0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19]
  private var pending: [UInt8] = []
  private var length: UInt64 = 0

  mutating func update(_ data: Data) {
    length &+= UInt64(data.count)
    pending.append(contentsOf: data)
    var offset = 0
    while pending.count - offset >= 64 {
      block(pending[offset..<offset + 64])
      offset += 64
    }
    pending.removeFirst(offset)
  }

  func hex() -> String {
    var copy = self
    var tail = copy.pending
    tail.append(0x80)
    while tail.count % 64 != 56 { tail.append(0) }
    let bits = length &* 8
    for shift in stride(from: 56, through: 0, by: -8) { tail.append(UInt8(truncatingIfNeeded: bits >> UInt64(shift))) }
    for offset in stride(from: 0, to: tail.count, by: 64) { copy.block(tail[offset..<offset + 64]) }
    return copy.state.map { word in
      let hex = String(word, radix: 16)
      return String(repeating: "0", count: 8 - hex.count) + hex
    }.joined()
  }

  private mutating func block(_ bytes: ArraySlice<UInt8>) {
    var w = [UInt32](repeating: 0, count: 64)
    let base = bytes.startIndex
    for i in 0..<16 {
      w[i] = UInt32(bytes[base + 4 * i]) << 24 | UInt32(bytes[base + 4 * i + 1]) << 16 | UInt32(bytes[base + 4 * i + 2]) << 8 | UInt32(bytes[base + 4 * i + 3])
    }
    func rotr(_ x: UInt32, _ n: UInt32) -> UInt32 { x >> n | x << (32 - n) }
    for i in 16..<64 {
      let s0 = rotr(w[i - 15], 7) ^ rotr(w[i - 15], 18) ^ (w[i - 15] >> 3)
      let s1 = rotr(w[i - 2], 17) ^ rotr(w[i - 2], 19) ^ (w[i - 2] >> 10)
      w[i] = w[i - 16] &+ s0 &+ w[i - 7] &+ s1
    }
    var (a, b, c, d, e, f, g, h) = (state[0], state[1], state[2], state[3], state[4], state[5], state[6], state[7])
    for i in 0..<64 {
      let t1 = h &+ (rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25)) &+ ((e & f) ^ (~e & g)) &+ PortableSHA256.k[i] &+ w[i]
      let t2 = (rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22)) &+ ((a & b) ^ (a & c) ^ (b & c))
      (h, g, f, e, d, c, b, a) = (g, f, e, d &+ t1, c, b, a, t1 &+ t2)
    }
    for (i, v) in [a, b, c, d, e, f, g, h].enumerated() { state[i] = state[i] &+ v }
  }
}

// MARK: - HTTP over URLSession

/// Routes URLSession's delegate callbacks to the exchange of each task; pins certificates.
final class SessionDelegate: NSObject, URLSessionDataDelegate, @unchecked Sendable {
  private let lock = NSLock()
  private var exchanges: [Int: Exchange] = [:]
  /// DER-encoded certificates the server must chain to (empty: the system trust store).
  let pinned: [Data]

  init(pinned: [Data]) {
    self.pinned = pinned
  }

  func register(_ task: URLSessionTask, _ exchange: Exchange) {
    lock.lock()
    exchanges[task.taskIdentifier] = exchange
    lock.unlock()
  }

  private func exchange(_ task: URLSessionTask, remove: Bool = false) -> Exchange? {
    lock.lock()
    defer { lock.unlock() }
    return remove ? exchanges.removeValue(forKey: task.taskIdentifier) : exchanges[task.taskIdentifier]
  }

  func urlSession(_ session: URLSession, didReceive challenge: URLAuthenticationChallenge,
                  completionHandler: @escaping @Sendable (URLSession.AuthChallengeDisposition, URLCredential?) -> Void) {
    #if canImport(Security)
    guard !pinned.isEmpty, challenge.protectionSpace.authenticationMethod == NSURLAuthenticationMethodServerTrust,
          let trust = challenge.protectionSpace.serverTrust
    else { return completionHandler(.performDefaultHandling, nil) }
    if evaluate(trust, host: challenge.protectionSpace.host) {
      completionHandler(.useCredential, URLCredential(trust: trust))
    } else {
      completionHandler(.cancelAuthenticationChallenge, nil)
    }
    #else
    completionHandler(.performDefaultHandling, nil)
    #endif
  }

  #if canImport(Security)
  /// Evaluates the server's trust against the pinned certificates only. A pinned leaf identifies the
  /// server by itself (checked as X.509: validity, signature); otherwise a pinned CA must have issued
  /// the chain for this host under the full TLS server policy (host name, key usage).
  private func evaluate(_ trust: SecTrust, host: String) -> Bool {
    let anchors = pinned.compactMap { SecCertificateCreateWithData(nil, $0 as CFData) }
    guard let chain = SecTrustCopyCertificateChain(trust) as? [SecCertificate], let leaf = chain.first else { return false }
    let leafIsPinned = pinned.contains(SecCertificateCopyData(leaf) as Data)
    let policy = leafIsPinned ? SecPolicyCreateBasicX509() : SecPolicyCreateSSL(true, host as CFString)
    guard SecTrustSetPolicies(trust, policy) == errSecSuccess,
          SecTrustSetAnchorCertificates(trust, anchors as CFArray) == errSecSuccess,
          SecTrustSetAnchorCertificatesOnly(trust, true) == errSecSuccess
    else { return false }
    return SecTrustEvaluateWithError(trust, nil)
  }
  #endif

  func urlSession(_ session: URLSession, task: URLSessionTask, needNewBodyStream completionHandler: @escaping @Sendable (InputStream?) -> Void) {
    completionHandler(exchange(task)?.takeBodyStream())  // a second request would need a replay: nil fails it
  }

  func urlSession(_ session: URLSession, dataTask: URLSessionDataTask, didReceive response: URLResponse,
                  completionHandler: @escaping @Sendable (URLSession.ResponseDisposition) -> Void) {
    exchange(dataTask)?.head(response)
    completionHandler(.allow)
  }

  func urlSession(_ session: URLSession, dataTask: URLSessionDataTask, didReceive data: Data) {
    exchange(dataTask)?.data(data)
  }

  func urlSession(_ session: URLSession, task: URLSessionTask, didCompleteWithError error: Error?) {
    exchange(task, remove: true)?.complete(error)
  }

  func urlSession(_ session: URLSession, task: URLSessionTask, willPerformHTTPRedirection response: HTTPURLResponse,
                  newRequest request: URLRequest, completionHandler: @escaping @Sendable (URLRequest?) -> Void) {
    completionHandler(nil)  // apü doesn't redirect; a 3xx is the response
  }
}

/// One request/response: the response head as a continuation, the body as an async stream.
final class Exchange: @unchecked Sendable {
  private let lock = NSLock()
  private var headContinuation: CheckedContinuation<HTTPURLResponse, Error>?
  private var bodyStream: InputStream?
  let body: AsyncThrowingStream<Data, Error>
  private let bodyContinuation: AsyncThrowingStream<Data, Error>.Continuation

  init(bodyStream: InputStream?) {
    self.bodyStream = bodyStream
    (body, bodyContinuation) = AsyncThrowingStream.makeStream(of: Data.self)
  }

  func waitForHead(_ continuation: CheckedContinuation<HTTPURLResponse, Error>) {
    lock.lock()
    headContinuation = continuation
    lock.unlock()
  }

  func takeBodyStream() -> InputStream? {
    lock.lock()
    defer { lock.unlock() }
    let stream = bodyStream
    bodyStream = nil
    return stream
  }

  private func takeHead() -> CheckedContinuation<HTTPURLResponse, Error>? {
    lock.lock()
    defer { lock.unlock() }
    let continuation = headContinuation
    headContinuation = nil
    return continuation
  }

  func head(_ response: URLResponse) {
    guard let response = response as? HTTPURLResponse else {
      takeHead()?.resume(throwing: URLError(.badServerResponse))
      return
    }
    takeHead()?.resume(returning: response)
  }

  func data(_ data: Data) { bodyContinuation.yield(data) }

  func complete(_ error: Error?) {
    takeHead()?.resume(throwing: error ?? URLError(.badServerResponse))
    if let error { bodyContinuation.finish(throwing: error) } else { bodyContinuation.finish() }
  }
}

/// A response body read in chunks or exact amounts (frames).
final class BodyReader {
  private var iterator: AsyncThrowingStream<Data, Error>.AsyncIterator?
  private var buffer: [UInt8] = []
  private var start = 0

  init(_ stream: AsyncThrowingStream<Data, Error>) {
    iterator = stream.makeAsyncIterator()
  }

  init(buffered: Data) {
    buffer = [UInt8](buffered)
  }

  /// The next piece of the body, nil at its end.
  func chunk() async throws -> Data? {
    if start < buffer.count {
      defer { buffer = []; start = 0 }
      return Data(buffer[start...])
    }
    guard iterator != nil else { return nil }
    if let data = try await iterator!.next() { return data }
    iterator = nil
    return nil
  }

  /// Exactly `count` bytes; nil if the body ended before the first of them.
  func read(_ count: Int) async throws -> [UInt8]? {
    while buffer.count - start < count {
      if start > 0 {
        buffer.removeFirst(start)
        start = 0
      }
      guard iterator != nil, let data = try await iterator!.next() else {
        iterator = nil
        if buffer.count == start { return nil }
        throw ApueError.truncated("incomplete frame")
      }
      buffer.append(contentsOf: data)
    }
    defer { start += count }
    return Array(buffer[start..<start + count])
  }

  func all(limit: Int = Frame.maxMessage) async throws -> Data {
    var out = Data()
    while let data = try await chunk() {
      out.append(data)
      guard out.count <= limit else { throw ApueError(502, "Bad Gateway", "response larger than \(limit) bytes") }
    }
    return out
  }
}

/// A response head and its body.
final class Response {
  let status: Int
  let http: HTTPURLResponse
  let body: BodyReader
  let task: URLSessionTask

  init(http: HTTPURLResponse, body: BodyReader, task: URLSessionTask) {
    self.status = http.statusCode
    self.http = http
    self.body = body
    self.task = task
  }

  func header(_ name: String) -> String? { http.value(forHTTPHeaderField: name) }

  var mediaType: String {
    (header("content-type") ?? "").split(separator: ";", maxSplits: 1).first.map { $0.trimmingCharacters(in: .whitespaces).lowercased() } ?? ""
  }

  func problem() async -> ApueError {
    let body = (try? await self.body.all()) ?? Data()
    if let parsed = try? JSONText.parse(body), case .object = parsed, let problem = try? parsed.json() {
      return ApueError(status: status, problem: problem)
    }
    return ApueError(status: status, problem: .object(["title": .string(ApueError.phrase(status))]))
  }
}

// MARK: - Operations

/// What the runtime needs to know about an op (embedded by the generator).
public struct ApueOp: Sendable {
  public enum Effect: String, Sendable { case safe, idempotent, unsafe }
  public enum Stream: String, Sendable { case none, server, client, bidi }
  let name: String
  let effect: Effect
  let stream: Stream
  /// The input/output schema has t.bytes() or t.file() somewhere.
  let inputBytes: Bool
  let outputBytes: Bool

  public init(_ name: String, _ effect: Effect, _ stream: Stream, inputBytes: Bool, outputBytes: Bool) {
    self.name = name
    self.effect = effect
    self.stream = stream
    self.inputBytes = inputBytes
    self.outputBytes = outputBytes
  }
}

/// Reads the values of a response: one for a JSON body, each MSG of a framed one, until END.
final class ResponseValues {
  private let op: ApueOp
  private let response: Response
  private var finished = false

  init(_ op: ApueOp, _ response: Response) {
    self.op = op
    self.response = response
  }

  func next() async throws -> Node? {
    if finished { return nil }
    let framed = response.mediaType == "application/apue+json"
    if response.status >= 400 || !framed {
      finished = true
      if response.status >= 400 { throw await response.problem() }
      let body = try await response.body.all()
      return body.isEmpty ? .null : try JSONText.parse(body)
    }
    var blobs: [Data] = []
    var chunks = Data()
    var open = false
    var total = 0
    while let header = try await response.body.read(8) {
      let length = Int(header[4]) << 24 | Int(header[5]) << 16 | Int(header[6]) << 8 | Int(header[7])
      guard length <= Frame.maxMessage else { throw ApueError.malformed("frame of \(length) bytes") }
      var payload: [UInt8] = []
      if length > 0 { payload = try await response.body.read(length) ?? [] }
      guard payload.count == length else { throw ApueError.truncated("incomplete frame") }
      switch header[0] {
      case Frame.blob:
        total += length
        guard total <= Frame.maxMessage else { throw ApueError.malformed("blobs of one message exceed \(Frame.maxMessage) bytes") }
        chunks.append(contentsOf: payload)
        open = true
        if header[1] & Frame.last != 0 {
          blobs.append(chunks)
          chunks = Data()
          open = false
        }
      case Frame.msg:
        guard !open else { throw ApueError.malformed("MSG frame inside an unfinished blob") }
        let json = try JSONText.parse(Data(payload))
        guard op.outputBytes else {
          guard blobs.isEmpty else { throw ApueError.malformed("unreferenced blobs") }
          return json
        }
        var used = Set<Int>()
        let value = try Frame.restore(json, blobs, &used)
        guard used.count == blobs.count else { throw ApueError.malformed("message references \(used.count) of \(blobs.count) blobs") }
        return value
      case Frame.end:
        finished = true
        let info = try JSONText.parse(Data(payload))
        guard case .number(let status)? = info["status"] else { throw ApueError.malformed("END without status") }
        if status >= 400 { throw ApueError(status: Int(exactly: status) ?? 502, problem: try (info["problem"] ?? .object([:])).json()) }
        return nil
      default:
        continue  // HEARTBEAT, CHECKPOINT and unknown frame types are ignored
      }
    }
    try Task.checkCancellation()
    throw ApueError.truncated("response ended without END frame")
  }
}

/// Writes a request body into a bound stream pair without blocking a thread: writes only what fits,
/// else waits (backing off up to 10 ms) — so cancelling the writing task always ends it.
final class BodyWriter: @unchecked Sendable {  // used by one task at a time
  private let input: InputStream
  private let output: OutputStream

  init(_ input: InputStream, _ output: OutputStream) {
    self.input = input
    self.output = output
    output.open()
  }

  /// False once nobody reads the body any more (the server answered, or the request ended): then
  /// the response carries the call's outcome, not this write.
  func write(_ data: Data) async throws -> Bool {
    var offset = data.startIndex
    var idle: UInt64 = 100_000
    while offset < data.endIndex {
      try Task.checkCancellation()
      if input.streamStatus == .notOpen {  // URLSession hasn't started reading: writing now would signal a closed reader
        try await Task.sleep(nanoseconds: idle)
        idle = min(idle * 2, 10_000_000)
        continue
      }
      if output.streamStatus == .error || output.streamStatus == .closed { return false }
      var written = 0
      if output.hasSpaceAvailable {
        written = data[offset...].withUnsafeBytes { raw in
          output.write(raw.bindMemory(to: UInt8.self).baseAddress!, maxLength: raw.count)
        }
        if written < 0 { return false }
      }
      if written > 0 {
        offset += written
        idle = 100_000
      } else {
        try await Task.sleep(nanoseconds: idle)
        idle = min(idle * 2, 10_000_000)
      }
    }
    return true
  }

  func close() {
    output.close()
  }
}

/// State of one streaming call, owned by an AsyncThrowingStream(unfolding:) — which calls it one
/// at a time. Dropping the stream (or cancelling the consuming task) cancels the HTTP request.
final class StreamCall: @unchecked Sendable {
  let client: ApueClient
  private let op: ApueOp
  private let open: @Sendable (StreamCall) async throws -> Response
  private var values: ResponseValues?
  private var response: URLSessionTask?
  private var writer: Task<Void, Never>?
  private var writerError: Error?
  private var uploads: [String] = []
  private var done = false

  init(_ client: ApueClient, _ op: ApueOp, open: @escaping @Sendable (StreamCall) async throws -> Response) {
    self.client = client
    self.op = op
    self.open = open
  }

  func adopt(uploads: [String]) { self.uploads += uploads }

  func adopt(writer: Task<Void, Never>) { self.writer = writer }

  func writerFailed(_ error: Error) {
    writerError = error
    response?.cancel()
  }

  func next() async throws -> Node? {
    if done { return nil }
    do {
      if values == nil {
        let response = try await open(self)
        self.response = response.task
        values = ResponseValues(op, response)
      }
      if let value = try await values!.next() { return value }
      await finish()
      return nil
    } catch {
      await finish()
      throw writerError ?? error
    }
  }

  private func finish() async {
    done = true
    writer?.cancel()  // the response is complete: nothing more will be read
    await client.deleteUploads(uploads)
    uploads = []
  }

  deinit {
    response?.cancel()
    writer?.cancel()
    if !uploads.isEmpty {
      let (client, uploads) = (client, uploads)
      Task { await client.deleteUploads(uploads) }
    }
  }
}

// MARK: - Client

/// Calls an apü API over URLSession. Thread-safe; one URLSession (and HTTP/2 connection) per client.
public final class ApueClient: Sendable {
  public struct Options: Sendable {
    /// PEM certificates to trust instead of the system store (a self-signed server certificate, or
    /// a private CA). Apple platforms only.
    public var pinnedCertificates: [String]
    /// The Authorization header for every request.
    public var authorization: String?
    /// Retries for safe and keyed calls (connection loss, 429/503, 409 retryable).
    public var retries: Int
    /// Base backoff in seconds; attempt n waits a random time in [0, backoff·2ⁿ], capped at maxBackoff.
    public var backoff: Double
    public var maxBackoff: Double
    /// URLSession's idle timeout (seconds without data) per request.
    public var idleTimeout: Double

    public init(pinnedCertificates: [String] = [], authorization: String? = nil, retries: Int = 2, backoff: Double = 0.1,
                maxBackoff: Double = 2, idleTimeout: Double = 60) {
      self.pinnedCertificates = pinnedCertificates
      self.authorization = authorization
      self.retries = retries
      self.backoff = backoff
      self.maxBackoff = maxBackoff
      self.idleTimeout = idleTimeout
    }
  }

  public let baseURL: URL
  public let options: Options
  let session: URLSession
  static let clientKey = CodingUserInfoKey(rawValue: "apue.client")!

  public init(baseURL: URL, options: Options = Options()) throws {
    guard baseURL.scheme == "https" else { throw ApueConfigurationError(description: "apü servers speak HTTPS") }
    let pinned = try options.pinnedCertificates.map(ApueClient.der)
    #if !canImport(Security)
    if !pinned.isEmpty {
      throw ApueConfigurationError(description: "certificate pinning needs Security.framework; add the CA to the system trust store")
    }
    #endif
    self.baseURL = baseURL
    self.options = options
    let configuration = URLSessionConfiguration.ephemeral
    configuration.urlCache = nil
    configuration.requestCachePolicy = .reloadIgnoringLocalCacheData
    configuration.timeoutIntervalForRequest = options.idleTimeout
    session = URLSession(configuration: configuration, delegate: SessionDelegate(pinned: pinned), delegateQueue: nil)
  }

  deinit {
    session.finishTasksAndInvalidate()
  }

  /// Lets running requests finish, then releases the connection.
  public func close() {
    session.finishTasksAndInvalidate()
  }

  static func der(_ pem: String) throws -> Data {
    let base64 = pem.split(whereSeparator: \.isNewline).filter { !$0.hasPrefix("-----") }.joined()
    guard pem.contains("-----BEGIN CERTIFICATE-----"), let der = Data(base64Encoded: base64) else {
      throw ApueConfigurationError(description: "not a PEM certificate")
    }
    return der
  }

  // -- HTTP -------------------------------------------------------------------------------------

  func url(_ path: String) -> URL {
    var base = baseURL.absoluteString
    while base.hasSuffix("/") { base.removeLast() }
    return URL(string: base + path)!
  }

  func send(_ method: String, _ path: String, headers: [String: String] = [:], body: Data? = nil,
            bodyStream: InputStream? = nil, file: URL? = nil) async throws -> Response {
    var request = URLRequest(url: url(path))
    request.httpMethod = method
    for (name, value) in headers { request.setValue(value, forHTTPHeaderField: name) }
    if let authorization = options.authorization { request.setValue(authorization, forHTTPHeaderField: "authorization") }
    let exchange = Exchange(bodyStream: bodyStream)
    let task: URLSessionTask
    if let file {
      task = session.uploadTask(with: request, fromFile: file)
    } else if let bodyStream {
      #if canImport(FoundationNetworking)
      request.httpBodyStream = bodyStream  // swift-corelibs-foundation reads it from the request
      #endif
      task = session.uploadTask(withStreamedRequest: request)
    } else if let body {
      task = session.uploadTask(with: request, from: body)
    } else {
      task = session.dataTask(with: request)
    }
    (session.delegate as! SessionDelegate).register(task, exchange)
    do {
      let head = try await withTaskCancellationHandler {
        try await withCheckedThrowingContinuation { continuation in
          exchange.waitForHead(continuation)
          task.resume()
        }
      } onCancel: {
        task.cancel()
      }
      return Response(http: head, body: BodyReader(exchange.body), task: task)
    } catch {
      if Task.isCancelled { throw CancellationError() }
      throw error
    }
  }

  /// Sends with retries (if `retry`): connection loss, 429/503 (Retry-After), 409 with retryable.
  func perform(_ method: String, _ path: String, headers: [String: String], body: Data?, retry: Bool) async throws -> Response {
    var attempt = 0
    while true {
      let response: Response
      do {
        response = try await send(method, path, headers: headers, body: body)
      } catch let error where retry && attempt < options.retries && ApueClient.transient(error) {
        attempt += 1
        try await pause(backoff(attempt))
        continue
      }
      guard retry && attempt < options.retries else { return response }
      if response.status == 429 || response.status == 503 {
        let hinted = ApueClient.retryAfter(response.header("retry-after"))
        _ = try? await response.body.all()
        attempt += 1
        try await pause(min(hinted ?? backoff(attempt), options.maxBackoff))
        continue
      }
      if response.status == 409 && response.mediaType == "application/problem+json" {
        let body = try await response.body.all()
        if let problem = try? JSONText.parse(body), problem["retryable"] == .bool(true) {
          attempt += 1
          try await pause(backoff(attempt))
          continue
        }
        return Response(http: response.http, body: BodyReader(buffered: body), task: response.task)
      }
      return response
    }
  }

  func backoff(_ attempt: Int) -> Double {
    Double.random(in: 0...1) * min(options.maxBackoff, options.backoff * pow(2, Double(attempt)))
  }

  func pause(_ seconds: Double) async throws {
    try await Task.sleep(nanoseconds: UInt64(max(0, seconds) * 1_000_000_000))
  }

  /// Connection-level failures worth another attempt (the request may not have arrived).
  static func transient(_ error: Error) -> Bool {
    guard let error = error as? URLError else { return false }
    return [.networkConnectionLost, .notConnectedToInternet, .cannotConnectToHost, .timedOut, .dnsLookupFailed, .cannotFindHost].contains(error.code)
  }

  /// Retry-After (RFC 9110 §10.2.3): delay-seconds or an HTTP-date (always GMT).
  static func retryAfter(_ value: String?) -> Double? {
    guard let value = value?.trimmingCharacters(in: .whitespaces), !value.isEmpty else { return nil }
    if value.allSatisfy(\.isASCII), value.allSatisfy(\.isNumber) { return Double(value) }
    let formatter = DateFormatter()
    formatter.locale = Locale(identifier: "en_US_POSIX")
    formatter.timeZone = TimeZone(identifier: "GMT")
    formatter.dateFormat = "EEE, dd MMM yyyy HH:mm:ss 'GMT'"
    guard let date = formatter.date(from: value) else { return nil }
    return max(0, date.timeIntervalSinceNow)
  }

  // -- uploads (bytes and file inputs) ----------------------------------------------------------

  /// Uploads content to /$uploads in one request; returns the upload's id (`{"$upload": id}`).
  public func upload(_ source: ApueFile) async throws -> String {
    let headers = ["upload-complete": "?1", "content-type": "application/octet-stream"]
    let response: Response
    switch source {
    case .upload(let id): return id
    case .data(let data): response = try await send("POST", "/$uploads", headers: headers, body: data)
    case .file(let url): response = try await send("POST", "/$uploads", headers: headers, file: url)
    }
    guard response.status == 201 else { throw await response.problem() }
    guard case .string(let id)? = try JSONText.parse(try await response.body.all())["upload"] else {
      throw ApueError(502, "Bad Gateway", "upload answered without an id")
    }
    return id
  }

  /// Deletes an upload (errors ignored: it expires anyway).
  public func deleteUpload(_ id: String) async {
    let escaped = id.addingPercentEncoding(withAllowedCharacters: ApueClient.unreserved) ?? id
    if let response = try? await send("DELETE", "/$uploads/\(escaped)") { _ = try? await response.body.all() }
  }

  func deleteUploads(_ ids: [String]) async {
    await withTaskGroup(of: Void.self) { group in
      for id in ids { group.addTask { await self.deleteUpload(id) } }
    }
  }

  /// Replaces bytes and files in a unary input by upload references (schema-directed on the server).
  func withUploads(_ value: Node, _ created: inout [String]) async throws -> Node {
    switch value {
    case .bytes(let data):
      let id = try await upload(.data(data))
      created.append(id)
      return .object(["$upload": .string(id)])
    case .file(let file):
      let id = try await upload(file)
      if case .upload = file {} else { created.append(id) }
      return .object(["$upload": .string(id)])
    case .array(let items):
      var out: [Node] = []
      for item in items { out.append(try await withUploads(item, &created)) }
      return .array(out)
    case .object(let members):
      var out: [String: Node] = [:]
      for (key, member) in members { out[key] = try await withUploads(member, &created) }
      return .object(out)
    default:
      return value
    }
  }

  // -- calls ------------------------------------------------------------------------------------

  static let unreserved = CharacterSet(charactersIn: "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-._~")
  static let maxGetURL = 2048
  static let accept = "application/apue+json, application/json;q=0.9, application/problem+json;q=0.8"

  static func encode<T: Encodable>(_ value: T) throws -> Node { try NodeEncoder.encode(value) }

  func decode<T: Decodable>(_ type: T.Type, _ node: Node) throws -> T {
    try NodeDecoder.decode(type, from: node, userInfo: [ApueClient.clientKey: self])
  }

  /// Method, path, headers and body of a call without a request stream (SPEC §5).
  func prepare(_ op: ApueOp, _ input: Node?, timeoutMs: Int?, idempotencyKey: String?) throws -> (String, String, [String: String], Data?) {
    var headers = ["accept": ApueClient.accept]
    if let timeoutMs { headers["apue-timeout"] = String(timeoutMs) }
    if op.effect == .safe {
      var path = "/\(op.name)"
      if let input {
        let canonical = try JSONText.string(input, canonical: true)
        path += "?i=" + (canonical.addingPercentEncoding(withAllowedCharacters: ApueClient.unreserved) ?? canonical)
      }
      if path.utf8.count <= ApueClient.maxGetURL { return ("GET", path, headers, nil) }
    }
    var body: Data?
    if let input {
      body = try JSONText.serialize(input)
      headers["content-type"] = "application/json"
    }
    if op.effect != .safe && op.stream == .none {
      headers["idempotency-key"] = "\"" + (idempotencyKey ?? UUID().uuidString.lowercased()) + "\""
    }
    return ("POST", "/\(op.name)", headers, body)
  }

  /// A unary call: uploads for bytes/file inputs (deleted afterwards), retries for safe/keyed calls.
  func call<O: Decodable>(_ op: ApueOp, _ input: Node?, timeoutMs: Int?, idempotencyKey: String?) async throws -> O {
    var created: [String] = []
    do {
      let value = op.inputBytes ? try await input.asyncMap { try await withUploads($0, &created) } : input
      let (method, path, headers, body) = try prepare(op, value, timeoutMs: timeoutMs, idempotencyKey: idempotencyKey)
      let response = try await perform(method, path, headers: headers, body: body, retry: true)
      let values = ResponseValues(op, response)
      var first: Node?
      while let value = try await values.next() { first = first ?? value }
      await deleteUploads(created)
      return try decode(O.self, first ?? .null)
    } catch {
      await deleteUploads(created)
      throw error
    }
  }

  /// A server stream: requested on first iteration, cancelled when the stream is dropped.
  func serverStream<O: Decodable & Sendable>(_ op: ApueOp, _ input: Result<Node?, Error>, timeoutMs: Int?) -> AsyncThrowingStream<O, Error> {
    let call = StreamCall(self, op) { call in
      var created: [String] = []
      do {
        var value = try input.get()
        if op.inputBytes { value = try await value.asyncMap { try await call.client.withUploads($0, &created) } }
        call.adopt(uploads: created)
        let (method, path, headers, body) = try call.client.prepare(op, value, timeoutMs: timeoutMs, idempotencyKey: nil)
        return try await call.client.perform(method, path, headers: headers, body: body, retry: op.effect != .unsafe)
      } catch {
        call.adopt(uploads: created)
        throw error
      }
    }
    return AsyncThrowingStream {
      guard let node = try await call.next() else { return nil }
      return try call.client.decode(O.self, node)
    }
  }

  /// A request stream (client or bidi): inputs are framed into the request body as they come.
  /// Never retried (the body can't be replayed).
  func requestStream<S: AsyncSequence & Sendable, O: Decodable & Sendable>(_ op: ApueOp, _ inputs: S, timeoutMs: Int?) -> AsyncThrowingStream<O, Error>
  where S.Element: Encodable {
    let call = StreamCall(self, op) { call in
      var input: InputStream?
      var output: OutputStream?
      Stream.getBoundStreams(withBufferSize: Frame.blobChunk, inputStream: &input, outputStream: &output)
      guard let input, let output else { throw URLError(.cannotCreateFile) }
      let writer = BodyWriter(input, output)
      call.adopt(writer: Task { [weak call] in
        defer { writer.close() }
        do {
          for try await item in inputs {
            guard try await writer.write(try Frame.message(ApueClient.encode(item), bytes: op.inputBytes)) else { return }
          }
          _ = try await writer.write(Frame.encode(Frame.end, Data("{\"status\":200}".utf8)))
        } catch is CancellationError {
          // the call ended (or was cancelled): nothing more to send
        } catch {
          call?.writerFailed(error)  // the inputs failed (their sequence threw, or encoding): so does the call
        }
      })
      var headers = ["accept": ApueClient.accept, "content-type": "application/apue+json"]
      if let timeoutMs { headers["apue-timeout"] = String(timeoutMs) }
      return try await call.client.send("POST", "/\(op.name)", headers: headers, bodyStream: input)
    }
    return AsyncThrowingStream {
      guard let node = try await call.next() else { return nil }
      return try call.client.decode(O.self, node)
    }
  }

  func clientStream<S: AsyncSequence & Sendable, O: Decodable & Sendable>(_ op: ApueOp, _ inputs: S, timeoutMs: Int?) async throws -> O
  where S.Element: Encodable {
    let stream: AsyncThrowingStream<O, Error> = requestStream(op, inputs, timeoutMs: timeoutMs)
    var first: O?
    for try await value in stream where first == nil { first = value }
    guard let first else { throw ApueError.malformed("client stream answered without a value") }
    return first
  }
}

extension Optional {
  func asyncMap<U>(_ transform: (Wrapped) async throws -> U) async rethrows -> U? {
    switch self {
    case .some(let value): return try await transform(value)
    case .none: return nil
    }
  }
}

// MARK: - Downloads

/// A t.download() output: `url` works as a plain link until `expires`; `stream()` resumes a lost
/// connection with Range + If-Range and verifies the SHA-256 when the server announced one.
public final class Download: Codable, Sendable, CustomStringConvertible {
  public let path: String
  public let size: Int
  public let type: String
  public let sha256: String?
  /// RFC 3339 / ISO 8601 (UTC).
  public let expires: String
  let client: ApueClient?

  private enum Keys: String, CodingKey { case path = "$download", size, type, sha256, expires }

  public required init(from decoder: Decoder) throws {
    let container = try decoder.container(keyedBy: Keys.self)
    path = try container.decode(String.self, forKey: .path)
    size = try container.decode(Int.self, forKey: .size)
    type = try container.decode(String.self, forKey: .type)
    sha256 = try container.decodeIfPresent(String.self, forKey: .sha256)
    expires = try container.decode(String.self, forKey: .expires)
    client = decoder.userInfo[ApueClient.clientKey] as? ApueClient
  }

  public func encode(to encoder: Encoder) throws {
    var container = encoder.container(keyedBy: Keys.self)
    try container.encode(path, forKey: .path)
    try container.encode(size, forKey: .size)
    try container.encode(type, forKey: .type)
    try container.encodeIfPresent(sha256, forKey: .sha256)
    try container.encode(expires, forKey: .expires)
  }

  /// Absolute when the download came from a client, else the path.
  public var url: URL { client?.url(path) ?? URL(string: path)! }

  public var expiresAt: Date? {
    let formatter = ISO8601DateFormatter()
    formatter.timeZone = TimeZone(identifier: "UTC")
    formatter.formatOptions = [.withInternetDateTime, .withFractionalSeconds]
    if let date = formatter.date(from: expires) { return date }
    formatter.formatOptions = [.withInternetDateTime]
    return formatter.date(from: expires)
  }

  public var description: String { "Download(\(url.absoluteString), size: \(size), type: \(type))" }

  /// The content as it arrives, resumed after connection loss within the client's retry budget.
  public func stream() -> AsyncThrowingStream<Data, Error> {
    let reader = DownloadReader(self)
    return AsyncThrowingStream { try await reader.next() }
  }

  /// The whole content in memory, verified.
  public func bytes() async throws -> Data {
    var out = Data(capacity: size)
    for try await chunk in stream() { out.append(chunk) }
    return out
  }
}

/// One download's progress; called one at a time by AsyncThrowingStream(unfolding:).
final class DownloadReader: @unchecked Sendable {
  private let download: Download
  private var received = 0
  private var etag: String?
  private var failures = 0
  private var skip = 0
  private var response: Response?
  private var hasher = SHA256Hasher()
  private var done = false

  init(_ download: Download) {
    self.download = download
  }

  deinit {
    response?.task.cancel()
  }

  private func retry(_ error: Error, _ client: ApueClient) async throws {
    response = nil
    failures += 1
    if failures > client.options.retries { throw error }
    try await client.pause(client.backoff(failures))
  }

  func next() async throws -> Data? {
    guard let client = download.client else { throw ApueConfigurationError(description: "a Download decoded without a client can't be read") }
    while !done {
      if response == nil {
        var headers = ["accept-encoding": "identity"]
        if received > 0 {
          headers["range"] = "bytes=\(received)-"
          if let etag { headers["if-range"] = etag }
        }
        let response: Response
        do {
          response = try await client.send("GET", download.path, headers: headers)
        } catch let error where ApueClient.transient(error) {
          try await retry(error, client)
          continue
        }
        if response.status >= 400 { throw await response.problem() }
        skip = 0
        if received == 0 {
          guard response.status == 200 else { throw ApueError(502, "Bad Gateway", "download answered \(response.status)") }
          etag = response.header("etag")
        } else if response.status == 206 {
          guard response.header("content-range")?.hasPrefix("bytes \(received)-") == true else {
            throw ApueError(502, "Bad Gateway", "download resumed at the wrong offset")
          }
        } else if response.status == 200, let etag, response.header("etag") == etag {
          skip = received  // the same content, sent whole: skip what we have
        } else {
          throw ApueError(502, "Bad Gateway", "the download changed while resuming")
        }
        self.response = response
      }
      do {
        guard var chunk = try await response!.body.chunk() else {
          if received == download.size {
            done = true
            response = nil
            break
          }
          try Task.checkCancellation()
          try await retry(URLError(.networkConnectionLost), client)  // truncated: resume
          continue
        }
        if skip > 0 {
          let cut = min(skip, chunk.count)
          chunk = chunk.dropFirst(cut)
          skip -= cut
          if chunk.isEmpty { continue }
        }
        guard received + chunk.count <= download.size else {
          throw ApueError(502, "Bad Gateway", "download larger than its announced \(download.size) bytes")
        }
        received += chunk.count
        hasher.update(chunk)
        return Data(chunk)
      } catch let error where ApueClient.transient(error) {
        try await retry(error, client)
      }
    }
    if let expected = download.sha256, hasher.hex() != expected {
      throw ApueError(502, "Bad Gateway", "download content does not match its SHA-256")
    }
    return nil
  }
}
